fn frame(t: i32) {
    let palette = [0xff0044, 0xff8800, 0xffee00, 0x00cc44, 0x0066ff, 0x8800cc];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(palette[(t / 20) % 6]);
    let sw: i32 = w / 6;
    let mut i: i32 = 0;
    while i < 6 {
        host::display::fill_rect(i * sw + 2, h - 22, sw - 4, 18, palette[i]);
        i = i + 1;
    }
    host::display::present();
}
